namespace sv_9c6c32a451fe47b4909888427f4a566f;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@* Displays the step progress bar with clickable completed steps *@

<nav class="step-indicator" aria-label="Application progress">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <button class="step @stepClass"
                disabled="@(!IsStepClickable(stepIndex))"
                @onclick="() => OnStepClicked.InvokeAsync(stepIndex)"
                aria-current="@(stepIndex == CurrentStep ? "step" : null)">
            <span class="step-number">
                @if (IsCompleted(stepIndex))
                {
                    <span class="checkmark">&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>
        @if (i < StepNames.Count - 1)
        {
            <span class="step-connector @(IsCompleted(stepIndex) ? "completed" : "")"></span>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public IReadOnlyList<string> StepNames { get; set; } = [];
    [Parameter, EditorRequired] public IReadOnlySet<int> CompletedSteps { get; set; } = new HashSet<int>();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private string GetStepClass(int index)
    {
        if (index == CurrentStep) return "active";
        if (IsCompleted(index)) return "completed";
        return "future";
    }

    private bool IsCompleted(int index) => CompletedSteps.Contains(index);
    private bool IsStepClickable(int index) => IsCompleted(index) && index != CurrentStep;
}

@* A single work history entry form *@

<div class="work-entry">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Company" @onchange="e => CompanyChanged(e.Value?.ToString() ?? "")" required />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Title" @onchange="e => TitleChanged(e.Value?.ToString() ?? "")" required />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@StartDate.ToString("yyyy-MM-dd")" @onchange="StartDateChanged" required />
        </div>

        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@(EndDate?.ToString("yyyy-MM-dd") ?? "")"
                   @onchange="EndDateChanged"
                   disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="IsCurrentChanged" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Description" @onchange="e => DescriptionChanged(e.Value?.ToString() ?? "")"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime StartDate { get; set; } = DateTime.Today;
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    public record WorkEntryData(string Company, string Title, DateTime StartDate, DateTime? EndDate, bool IsCurrent, string Description);

    private Task NotifyChanged() => OnChanged.InvokeAsync(
        new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));

    private async Task CompanyChanged(string value) { Company = value; await NotifyChanged(); }
    private async Task TitleChanged(string value) { Title = value; await NotifyChanged(); }
    private async Task DescriptionChanged(string value) { Description = value; await NotifyChanged(); }

    private async Task StartDateChanged(ChangeEventArgs e)
    {
        if (DateTime.TryParse(e.Value?.ToString(), out var date)) StartDate = date;
        await NotifyChanged();
    }

    private async Task EndDateChanged(ChangeEventArgs e)
    {
        EndDate = DateTime.TryParse(e.Value?.ToString(), out var date) ? date : null;
        await NotifyChanged();
    }

    private async Task IsCurrentChanged(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        await NotifyChanged();
    }
}

