    private async Task RelationshipChanged(string value) { Relationship = value; await NotifyChanged(); }
    private async Task EmailChanged(string value) { Email = value; await NotifyChanged(); }
    private async Task PhoneChanged(string value) { Phone = value; await NotifyChanged(); }
}

