@* Step 1: Personal Information *@

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="FullName" @bind:event="oninput" placeholder="Enter your full name" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Email" @bind:event="oninput" placeholder="you@example.com" />
        @if (IsValidatingEmail)
        {
            <span class="validation-hint">Validating email...</span>
        }
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" @bind="Address" @bind:event="oninput" placeholder="Street, City, State, ZIP"></textarea>
    </div>

    <div class="step-actions">
        <button class="btn-primary" @onclick="HandleNext" disabled="@IsValidatingEmail">Next</button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfo> OnNext { get; set; }
    [Parameter, EditorRequired] public IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidatingEmail;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(FullName))
        { ErrorMessage = "Full name is required."; return; }
        if (string.IsNullOrWhiteSpace(Email))
        { ErrorMessage = "Email is required."; return; }
        if (string.IsNullOrWhiteSpace(Phone))
        { ErrorMessage = "Phone is required."; return; }
        if (string.IsNullOrWhiteSpace(Address))
        { ErrorMessage = "Address is required."; return; }

        IsValidatingEmail = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Email.Trim());
            if (!isValid)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
        }
        finally
        {
            IsValidatingEmail = false;
        }

        await OnNext.InvokeAsync(new PersonalInfo(FullName.Trim(), Email.Trim(), Phone.Trim(), Address.Trim()));
    }
}

