@* Step 4: Cover Letter *@

<div class="step-content">
    <h2>Cover Letter</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Write your cover letter below</label>
        <textarea class="cover-letter-input"
                  rows="12"
                  maxlength="@MaxLength"
                  @bind="CoverLetterText"
                  @bind:event="oninput"
                  placeholder="Tell us why you'd be a great fit..."></textarea>
        <span class="char-count @(CoverLetterText.Length > MaxLength ? "over-limit" : "")">
            @CoverLetterText.Length / @MaxLength characters
        </span>
    </div>

    <div class="step-actions">
        <button class="btn-outline" @onclick="OnBack">Back</button>
        <button class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetterText { get; set; } = "";
    [Parameter] public EventCallback<string> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private const int MaxLength = 2000;
    private string? ErrorMessage;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetterText))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }

        if (CoverLetterText.Length > MaxLength)
        {
            ErrorMessage = $"Cover letter must not exceed {MaxLength} characters.";
            return;
        }

        await OnNext.InvokeAsync(CoverLetterText);
    }
}

