@page "/apply"
@using sv_9c6c32a451fe47b4909888427f4a566f.Components.Pages.Apply
@inject IApplicationService ApplicationService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="currentStep"
                   StepNames="stepNames"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep FullName="@personalFullName"
                              Email="@personalEmail"
                              Phone="@personalPhone"
                              Address="@personalAddress"
                              ApplicationService="ApplicationService"
                              OnNext="HandlePersonalNext" />
            break;

        case 1:
            <WorkHistoryStep Entries="workEntries"
                             OnNext="HandleWorkNext"
                             OnBack="GoBack" />
            break;

        case 2:
            <ReferencesStep References="references"
                            OnNext="HandleReferencesNext"
                            OnBack="GoBack" />
            break;

        case 3:
            <CoverLetterStep CoverLetterText="@coverLetter"
                             OnNext="HandleCoverLetterNext"
                             OnBack="GoBack" />
            break;

        case 4:
            <ReviewStep Personal="@GetPersonalInfo()"
                        WorkEntries="workEntries"
                        References="references"
                        CoverLetter="@coverLetter"
                        ApplicationService="ApplicationService"
                        OnEditSection="GoToStep"
                        OnBack="GoBack" />
            break;
    }
</div>

@code {
    private int currentStep;
    private readonly HashSet<int> completedSteps = new();
    private static readonly IReadOnlyList<string> stepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    // Step 1 state
    private string personalFullName = "";
    private string personalEmail = "";
    private string personalPhone = "";
    private string personalAddress = "";

    // Step 2 state
    private List<WorkHistoryStep.EntryModel> workEntries = [new()];

    // Step 3 state
    private List<ReferencesStep.RefModel> references = [new(), new()];

    // Step 4 state
    private string coverLetter = "";

    private PersonalInfo GetPersonalInfo() => new(personalFullName, personalEmail, personalPhone, personalAddress);

    private void HandlePersonalNext(PersonalInfo info)
    {
        personalFullName = info.FullName;
        personalEmail = info.Email;
        personalPhone = info.Phone;
        personalAddress = info.Address;
        completedSteps.Add(0);
        currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.EntryModel> entries)
    {
        workEntries = entries;
        completedSteps.Add(1);
        currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.RefModel> refs)
    {
        references = refs;
        completedSteps.Add(2);
        currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        coverLetter = text;
        completedSteps.Add(3);
        currentStep = 4;
    }

    private void GoBack() => currentStep = Math.Max(0, currentStep - 1);

    private void GoToStep(int step)
    {
        if (completedSteps.Contains(step) || step == currentStep)
            currentStep = step;
    }
}

